macro_rules! deps {
    () => {
        Token!();
        CommentKind!();
        AttrStyle!();
        Lifetime!();
        InvisibleOrigin!();
        Lit!();
        IdentIsRaw!();
    };
}

macro_rules! TokenKind {
    () => {
        deps!();
        # [derive (Clone , Copy , PartialEq , Encodable , Decodable , Debug , HashStable_Generic)] pub enum TokenKind { # [doc = " `=`"] Eq , # [doc = " `<`"] Lt , # [doc = " `<=`"] Le , # [doc = " `==`"] EqEq , # [doc = " `!=`"] Ne , # [doc = " `>=`"] Ge , # [doc = " `>`"] Gt , # [doc = " `&&`"] AndAnd , # [doc = " `||`"] OrOr , # [doc = " `!`"] Bang , # [doc = " `~`"] Tilde , Plus , Minus , Star , Slash , Percent , Caret , And , Or , Shl , Shr , PlusEq , MinusEq , StarEq , SlashEq , PercentEq , CaretEq , AndEq , OrEq , ShlEq , ShrEq , # [doc = " `@`"] At , # [doc = " `.`"] Dot , # [doc = " `..`"] DotDot , # [doc = " `...`"] DotDotDot , # [doc = " `..=`"] DotDotEq , # [doc = " `,`"] Comma , # [doc = " `;`"] Semi , # [doc = " `:`"] Colon , # [doc = " `::`"] PathSep , # [doc = " `->`"] RArrow , # [doc = " `<-`"] LArrow , # [doc = " `=>`"] FatArrow , # [doc = " `#`"] Pound , # [doc = " `$`"] Dollar , # [doc = " `?`"] Question , # [doc = " Used by proc macros for representing lifetimes, not generated by lexer right now."] SingleQuote , # [doc = " `(`"] OpenParen , # [doc = " `)`"] CloseParen , # [doc = " `{`"] OpenBrace , # [doc = " `}`"] CloseBrace , # [doc = " `[`"] OpenBracket , # [doc = " `]`"] CloseBracket , # [doc = " Invisible opening delimiter, produced by a macro."] OpenInvisible (InvisibleOrigin) , # [doc = " Invisible closing delimiter, produced by a macro."] CloseInvisible (InvisibleOrigin) , Literal (Lit) , # [doc = " Identifier token."] # [doc = " Do not forget about `NtIdent` when you want to match on identifiers."] # [doc = " It's recommended to use `Token::{ident,uninterpolate}` and"] # [doc = " `Parser::token_uninterpolated_span` to treat regular and interpolated"] # [doc = " identifiers in the same way."] Ident (Symbol , IdentIsRaw) , # [doc = " This identifier (and its span) is the identifier passed to the"] # [doc = " declarative macro. The span in the surrounding `Token` is the span of"] # [doc = " the `ident` metavariable in the macro's RHS."] NtIdent (Ident , IdentIsRaw) , # [doc = " Lifetime identifier token."] # [doc = " Do not forget about `NtLifetime` when you want to match on lifetime identifiers."] # [doc = " It's recommended to use `Token::{ident,uninterpolate}` and"] # [doc = " `Parser::token_uninterpolated_span` to treat regular and interpolated"] # [doc = " identifiers in the same way."] Lifetime (Symbol , IdentIsRaw) , # [doc = " This identifier (and its span) is the lifetime passed to the"] # [doc = " declarative macro. The span in the surrounding `Token` is the span of"] # [doc = " the `lifetime` metavariable in the macro's RHS."] NtLifetime (Ident , IdentIsRaw) , # [doc = " A doc comment token."] # [doc = " `Symbol` is the doc comment's data excluding its \"quotes\" (`///`, `/**`, etc)"] # [doc = " similarly to symbols in string literal tokens."] DocComment (CommentKind , ast :: AttrStyle , Symbol) , # [doc = " End Of File"] Eof , }
    };
}

TokenKind!();